    @Override
    public void visitElement(@NonNull XmlContext context, @NonNull Element element) {
        Element parent = element.getParentNode() instanceof Element ? (Element) element.getParentNode() : null;
        if (parent == null || !TAG_LINEAR_LAYOUT.equals(parent.getTagName())) {
            return;
        }

        String orientation = parent.getAttributeNS(ANDROID_URI, ATTR_ORIENTATION);
        boolean horizontal = orientation == null || orientation.isEmpty() || VALUE_HORIZONTAL.equals(orientation);

        String weight = element.getAttributeNS(ANDROID_URI, ATTR_LAYOUT_WEIGHT);
        if (weight == null || weight.isEmpty() || Float.parseFloat(weight) == 0f) {
            return;
        }

        if (horizontal) {
            Attr height = element.getAttributeNodeNS(ANDROID_URI, ATTR_LAYOUT_HEIGHT);
            if (height != null && isZeroDp(height.getValue())) {
                context.report(ISSUE, height, context.getLocation(height),
                        "Suspicious 0dp height in a horizontal LinearLayout: it will make this view invisible");
            }
        } else {
            Attr width = element.getAttributeNodeNS(ANDROID_URI, ATTR_LAYOUT_WIDTH);
            if (width != null && isZeroDp(width.getValue())) {
                context.report(ISSUE, width, context.getLocation(width),
                        "Suspicious 0dp width in a vertical LinearLayout: it will make this view invisible");
            }
        }
    }

    private static boolean isZeroDp(@Nullable String value) {
        if (value == null || value.isEmpty()) {
            return false;
        }
        if ("0dp".equals(value) || "0dip".equals(value) || "0sp".equals(value) || "0px".equals(value) || "0pt".equals(value) || "0in".equals(value) || "0mm".equals(value)) {
            return true;
        }
        if (value.length() > 0) {
            int i = 0;
            boolean seenDot = false;
            for (; i < value.length(); i++) {
                char c = value.charAt(i);
                if (c == '.') {
                    if (seenDot) return false;
                    seenDot = true;
                } else if (c < '0' || c > '9') {
                    break;
                }
            }
            if (i == 0) return false;
            String unit = value.substring(i).trim();
            return unit.isEmpty() || unit.equals("dp") || unit.equals("dip") || unit.equals("sp") || unit.equals("px") || unit.equals("pt") || unit.equals("in") || unit.equals("mm");
        }
        return false;
    }
}

